// One item per meeting that has an external guest.
// The guest = first attendee that is not you (not marked self/organizer).
const out = [];
for (const item of $input.all()) {
  const ev = item.json;
  if (!ev || !ev.start) continue;
  const attendees = ev.attendees || [];
  const guest = attendees.find(a => a && a.email && !a.self && !a.organizer);
  if (!guest) continue; // solo events, focus blocks etc. get no brief
  out.push({
    json: {
      event_title: ev.summary || 'Meeting',
      event_time: (ev.start.dateTime || ev.start.date || ''),
      guest_email: guest.email,
      guest_name: guest.displayName || guest.email.split('@')[0],
    },
  });
}
return out;

// Assemble the one-message brief from the three lookups.
const guest = $('Extract Guest').first().json;

let lead = {};
try {
  const row = $('Lookup Lead in CRM').first();
  if (row && row.json && row.json.email) lead = row.json;
} catch (e) { /* no CRM row found */ }

const emails = $input.all()
  .map(i => i.json)
  .filter(m => m && (m.subject || m.Subject || m.snippet));

let history = 'No past emails found.';
if (emails.length) {
  history = emails.slice(0, 5).map(m => {
    const subject = m.subject || m.Subject || '(no subject)';
    const snippet = m.snippet ? ' - ' + String(m.snippet).slice(0, 120) : '';
    return '• ' + subject + snippet;
  }).join('\n');
}

const lines = [
  '📋 Briefing: ' + guest.event_title,
  '🕐 When: ' + guest.event_time,
  '',
  '👤 Who: ' + (lead.name || guest.guest_name) + ' (' + guest.guest_email + ')',
  lead.company ? '🏢 Company: ' + lead.company : '🏢 Company: not in CRM',
  lead.source ? '🔎 How they found you: ' + lead.source : '',
  lead.notes ? '📝 Notes: ' + lead.notes : '',
  '',
  '✉️ Recent emails:',
  history,
].filter(l => l !== '');

return [{ json: { text: lines.join('\n') } }];

